script:
// 청주 민간공원 특례사업지 — 개발 전후 지표온도 비교 (1회 실행용, 지도 레이어 없음)
// 개발 구역: 개발 전 숲(NDVI>=0.55) -> 개발 후 NDVI 0.25 이상 하락 / 유지 구역: 두 시기 모두 숲
// 효과 = dLST(개발) - dLST(숲 유지). LST는 장면별 청주 시가지 평균 대비 편차.
var aoi = ee.Geometry.Rectangle([127.38, 36.56, 127.56, 36.70]);
var SITES = [
  {name: '잠두봉', lon: 127.4785, lat: 36.6150, r: 500},
  {name: '매봉',   lon: 127.4739, lat: 36.6216, r: 500},
  {name: '구룡',   lon: 127.4640, lat: 36.6182, r: 700},
  {name: '원봉',   lon: 127.5175, lat: 36.6092, r: 600},
  {name: '월명',   lon: 127.4550, lat: 36.6450, r: 700},
  {name: '새적굴', lon: 127.4930, lat: 36.6560, r: 700}
];
var BEFORE = ['2013-04-01', '2016-10-01'], AFTER = ['2023-04-01', '2025-10-01'];
var FOREST = 0.55, DROP = 0.25;
function isNull(v) { return ee.Algorithms.IsEqual(v, null); }
function diff(a, b) { return ee.Algorithms.If(isNull(a), null, ee.Algorithms.If(isNull(b), null, ee.Number(a).subtract(ee.Number(b)))); }
function fmt(v) { return ee.Algorithms.If(isNull(v), 'NA', ee.Number(v).format('%.2f')); }
function prep(img) {
  var qa = img.select('QA_PIXEL');
  var clear = qa.bitwiseAnd(1 << 1).eq(0).and(qa.bitwiseAnd(1 << 3).eq(0)).and(qa.bitwiseAnd(1 << 4).eq(0)).and(qa.bitwiseAnd(1 << 5).eq(0));
  var sr = img.select(['SR_B4', 'SR_B5']).multiply(0.0000275).add(-0.2);
  var ndvi = sr.normalizedDifference(['SR_B5', 'SR_B4']).rename('NDVI');
  var st = img.select('ST_B10');
  var lst = st.multiply(0.00341802).add(149.0).subtract(273.15).rename('LST');
  return ndvi.addBands(lst).toFloat().updateMask(clear.and(st.gt(0))).copyProperties(img, ['system:time_start']);
}
function composite(range) {
  var col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2').merge(ee.ImageCollection('LANDSAT/LC09/C02/T1_L2'))
    .filterBounds(aoi).filterDate(range[0], range[1]).filter(ee.Filter.calendarRange(6, 9, 'month'))
    .filter(ee.Filter.lt('CLOUD_COVER', 40)).map(prep)
    .map(function (img) { return img.set('m', img.select('LST').reduceRegion({reducer: ee.Reducer.mean(), geometry: aoi, scale: 300, maxPixels: 1e9}).get('LST')); })
    .filter(ee.Filter.notNull(['m']))
    .map(function (img) { return img.addBands(img.select('LST').subtract(ee.Number(img.get('m'))).rename('LSTa').toFloat()); });
  return {n: col.size(), img: col.select(['NDVI', 'LSTa']).median()};
}
var B = composite(BEFORE), A = composite(AFTER);
var ndviB = B.img.select('NDVI'), ndviA = A.img.select('NDVI');
var dLST = A.img.select('LSTa').subtract(B.img.select('LSTa')).rename('dLST');
var notWater = ee.ImageCollection('ESA/WorldCover/v200').first().neq(80);
var cleared = ndviB.gte(FOREST).and(ndviB.subtract(ndviA).gte(DROP)).and(notWater).rename('c');
var stable = ndviB.gte(FOREST).and(ndviA.gte(FOREST)).and(notWater).rename('s');
function meanOf(mask, geom) {
  return dLST.updateMask(mask).reduceRegion({reducer: ee.Reducer.mean().combine(ee.Reducer.count(), null, true), geometry: geom, scale: 30, maxPixels: 1e10, tileScale: 4});
}
var cityC = meanOf(cleared, aoi), cityS = meanOf(stable, aoi);
var rows = ee.FeatureCollection(SITES.map(function (s) {
  var g = ee.Geometry.Point([s.lon, s.lat]).buffer(s.r);
  var near = cleared.clip(g).unmask(0).focalMax({radius: 300, units: 'meters'}).and(cleared.not());
  var c = meanOf(cleared, g), st = meanOf(stable, g), nr = meanOf(near, g.buffer(300));
  var areaHa = ee.Number(cleared.multiply(ee.Image.pixelArea()).reduceRegion({reducer: ee.Reducer.sum(), geometry: g, scale: 30, maxPixels: 1e9}).get('c')).divide(1e4);
  return ee.Feature(null, {name: s.name, ha: areaHa, nC: c.get('dLST_count'), dC: c.get('dLST_mean'), dS: st.get('dLST_mean'),
    eff: diff(c.get('dLST_mean'), st.get('dLST_mean')), nb: diff(nr.get('dLST_mean'), st.get('dLST_mean'))});
}));
var siteTxt = rows.iterate(function (f, acc) {
  f = ee.Feature(f);
  return ee.String(acc).cat(f.get('name')).cat(', ').cat(fmt(f.get('ha'))).cat(', ').cat(fmt(f.get('dC'))).cat(', ')
    .cat(fmt(f.get('dS'))).cat(', ').cat(fmt(f.get('eff'))).cat(', ').cat(fmt(f.get('nb'))).cat(' | ');
}, 'name, 개발ha, dLST개발, dLST숲유지, 개발효과, 주변영향 | ');
var out = ee.Dictionary({
  scenes_before: B.n, scenes_after: A.n,
  city_dLST_cleared: fmt(cityC.get('dLST_mean')), city_n_cleared: cityC.get('dLST_count'),
  city_dLST_stable: fmt(cityS.get('dLST_mean')), city_n_stable: cityS.get('dLST_count'),
  city_effect: fmt(diff(cityC.get('dLST_mean'), cityS.get('dLST_mean'))),
  sites: siteTxt
});
out.evaluate(function (r, err) { print(err ? ('ERROR: ' + err) : ('RESULT_JSON ' + JSON.stringify(r))); });
